  "settings.copilotCompletion": "GitHub-Copilot-Autovervollständigung",
  "settings.copilotCompletionHelp": "Bietet GitHub Copilot als zweiten Anbieter für die Autovervollständigung in Code-Dateien an. Ollama bleibt der Standard; nichts wird gesendet, bevor sich unten ein Projekt anmeldet.",
  "settings.copilotCloudNotice": "Copilot ist ein Cloud-Dienst. Bei einem Projekt, das zustimmt, verlässt der Inhalt der bearbeiteten Code-Dateien diesen Rechner, und der Sprachserver kann den Rest dieses Projektordners lesen. Er läuft in der Sandbox: nur lesend, nur dieses eine Projekt, ohne Zugriff auf deinen Home-Ordner oder andere Zugangsdaten.",
