  "settings.themeVars": "Theme-Farben",
  "settings.themeVars.help": "Das aktive Theme Variable für Variable neu einfärben – Flächen, Text, Rahmen, Akzent, Statusfarben – in einem eigenen Fenster, zusammen mit dem Eckenstil. Die Überschreibungen gelten in jedem Theme, nicht nur in diesem.",
  "settings.themeVars.open": "Anpassen…",
  "theme.title": "Theme-Farben",
  "theme.intro": "Jeder Wert hier überschreibt das Token des aktiven Themes – in diesem und in jedem anderen Theme – bis du ihn zurücksetzt. Farben sind #rrggbb, oder #rrggbbaa, wo ein Wert durchscheinend bleiben soll.",
