  "theme.none": "Nichts überschrieben",
  "theme.presets": "Gespeicherte Themes",
  "theme.presets.help":
    "Legt das ganze Erscheinungsbild unter einem Namen ab — Basis-Theme, Akzent, jede hier geänderte Farbe und den Eckenstil — damit du später darauf zurückkommen oder zwei Paletten nebeneinander halten kannst.",
  "theme.presets.name": "Diesem Look einen Namen geben",
