    "Noch nichts gespeichert. Gib dem aktuellen Look einen Namen, dann landet er hier.",
  "theme.presets.load": "Laden",
  "theme.presets.loadHelp": "Diesen Look anwenden — Basis-Theme, Akzent, Farben und Ecken",
  "theme.presets.update": "Mit dem aktuellen Look überschreiben",
