  "theme.presets.confirm": "Löschen?",
  "theme.presets.meta": "{theme} · {n} Farben",
  "theme.presets.metaPlain": "{theme} · Theme-Farben unverändert",
  "theme.palette": "Farben in diesem Theme",
  "theme.palette.pick": "Aus den Farben wählen, die dieses Theme bereits verwendet",
  "theme.group.surfaces": "Flächen",
  "theme.group.surfaces.help": "Das Fenster, seine Panels und die Kopfleisten darüber – die Tab-Leisten der Unterfenster und die Kopfzeilen des Dateipanels, die sich eine zweite Fläche teilen. Die obere Leiste der App folgt hier --bg-header, bis du ihr unter „Obere Leiste“ eine eigene Fläche gibst.",
  "theme.group.topframe": "Obere Leiste",
  "theme.group.topframe.help": "{app}s eigene Titelleiste – der Streifen mit Uhr, Projekt-Pills und Fensterknöpfen. Drei Schichten bilden sie: eine Fläche, ein Akzentschleier darüber und die Naht darunter, die sagt, wo die Chrome der App endet und ihr Inhalt beginnt. Jede folgt einem geteilten Token, bis du sie setzt – so lässt sich die Leiste umfärben, ohne dass der Akzent im restlichen Fenster mitzieht. Die drei Textstufen darunter werden für den gesamten Teilbaum der Leiste umgesetzt, ein Wert bewegt also jede Beschriftung darauf – die Menüs, die aus der Leiste aufklappen, behalten die Schrift des Themes.",
  "theme.group.subwindow": "Unterfenster",
  "theme.group.subwindow.help": "Die eigene Kopfleiste eines Unterfensters – die Tab-Leiste über jedem Pane – plus die beiden Marker, die sagen, welches Unterfenster den Fokus hat. Die Leiste teilt sich die zweite Chrome-Fläche der App mit jeder Kopfzeile des Dateipanels, und ihre Marker lesen den blanken Akzent; nichts davon ließ sich bisher einzeln bewegen. Setz hier eine Textstufe, und die ganze Leiste folgt: Tab-Beschriftungen, Griff, Pfeile, Chips.",
  "theme.group.sidepanel": "Seitenpanel",
  "theme.group.sidepanel.help": "Das Dateipanel, das vom Rand hereinfährt – für sich allein. Jeder Wert hier folgt dem gemeinsamen Token, das er sonst läse; das Panel löst sich also erst vom Rest des Fensters, wenn du einen setzt – und die Kopfzeilen bewegen sich, ohne die Tab-Leisten der Unterfenster mitzunehmen.",
  "theme.group.alerts": "Alarm-Leiste",
  "theme.group.alerts.help": "Die Alarm-Gruppe unter dem Dateibaum – dringende Mails, die nächsten Termine, fällige Karten. Ihr Aussehen leitet sich aus Akzent, Fenstergrund und Statusfarben ab; diese Werte sind diese Ableitung, sodass sich die Leiste umtönen lässt, ohne das zu bewegen, wovon sie borgt.",
  "theme.group.text": "Text",
  "theme.group.text.help": "Die drei Textstufen, von hell nach gedämpft.",
  "theme.group.borders": "Rahmen",
  "theme.group.borders.help": "Trennlinien und Umrisse — die sichtbare und die zarte.",
  "theme.group.accent": "Akzent",
  "theme.group.accent.help": "Der Farbton des Themes und seine Zustände. Die Akzentfarbe selbst ist eine eigene themeübergreifende Einstellung – eine Vorgabe oder eine beliebige andere Farbe wählen; der Rest leitet sich daraus ab, bis er hier gesetzt wird.",
  "theme.group.controls": "Bedienelemente",
  "theme.group.controls.help": "Eingabefelder und Schaltflächen sowie die neutralen Hover- und Einlege-Schleier über jeder Fläche.",
  "theme.group.status": "Status",
  "theme.group.status.help": "Erfolg, Warnung und Gefahr sowie die Farbtöne der Aufgabenzustände daneben.",
