  "settings.claudeRemote": "Claude-Fernsteuerung",
  "mcpSecurity.title": "MCP-Sitzungszugriff",
  "mcpSecurity.help": "Berechtigungen gelten nur für diese laufende Sitzung. Neue Root-Sitzungen behalten die bisherigen Standardrechte; Mail-Leser erhalten zunächst nur Mail-Zugriff. Ohne Schreibrechte ist der Zugriff schreibgeschützt. Daten für einen Agenten mit Netzwerkzugriff können diesen Computer verlassen. Eingeschränkte Kalender- und Board-Änderungen erfordern immer eine Prüfung. Ein Entzug ist für den Tab endgültig: sein Agent wird ab dann abgewiesen, und nur ein erneutes Öffnen des Tabs vergibt ein neues Token.",
  "mcpSecurity.refresh": "Aktualisieren",
  "mcpSecurity.empty": "Keine aktiven MCP-Sitzungen.",
  "mcpSecurity.headless": "Tabs, die {app} Mobile ohne offenes Fenster gestartet hat, erhalten ihre Zeitplan-, Push- und Hilfe-Werkzeuge vom Mobile-Hintergrunddienst, nicht von diesem Fenster. Ihre Sitzungen werden hier nicht aufgeführt. Sie enden, wenn der Tab geschlossen wird oder der Dienst stoppt. Ihre Push- und Release-Anfragen werden abgelehnt, bis der Tab aus diesem Fenster neu gestartet wird.",
  "mcpSecurity.write": "Kalender-, Board- und Entwurfsänderungen erlauben",
  "mcpSecurity.revoke": "Zugriff widerrufen",
  "mcpSecurity.all": "Alle, einschließlich zukünftiger Einträge",
  "mcpSecurity.calendars": "Sichtbare Kalender",
  "mcpSecurity.projects": "Sichtbare Projekte und Board-Karten",
  "mcpSecurity.accounts": "Sichtbare Mail-Konten (Kontofreigabe gilt weiterhin)",
  "mcpSecurity.unassigned": "Karten ohne Projekt",
  "mcpSecurity.family.calendar": "Kalenderwerkzeuge",
  "mcpSecurity.family.board": "Board-Werkzeuge",
  "mcpSecurity.family.projects": "Projektübersichten",
  "mcpSecurity.family.mail": "Mail-Werkzeuge",
  "mcpSecurity.agent": "Root-Agent",
  "mcpSecurity.local_model": "Lokales Modell",
  "mcpSecurity.reader": "Mail-Leser",
  "mcpSecurity.audit": "Letzte MCP-Aktivitäten",
  "mcpSecurity.auditHelp": "Die letzten 50 von bis zu 500 Einträgen im Arbeitsspeicher dieses App-Laufs. Einträge enthalten Sitzung, Werkzeug, Entscheidung, Zeitangaben und eine feste Begründungskategorie (bei Zeitplan-Sitzungen auch das Ziel), aber keine Zugangsdaten, Argumente oder Nachrichtentexte. Anfragen, die schon vor der Anmeldung abgewiesen wurden, erscheinen als „Keine Sitzung“ und sind eigens begrenzt. Ein Eintrag gehört zum Token des Tabs: Alles, was der Agent in diesem Tab startet (ein Hook, ein Skript, ein Build), erbt das Token und kann die Werkzeuge als dieser Tab aufrufen – ein Eintrag ist also der des Tabs, nicht unbedingt ein Aufruf des Agenten selbst.",
  "mcpSecurity.time": "Zeit",
  "mcpSecurity.caller": "Sitzung",
  "mcpSecurity.tool": "Werkzeug",
  "mcpSecurity.outcome": "Ergebnis",
  "mcpSecurity.allowed": "Erlaubt",
  "mcpSecurity.denied": "Zugriff verweigert",
  "mcpSecurity.refused": "Anfrage abgelehnt",
  "mcpSecurity.protocol": "Protokollanfrage",
  "mcpSecurity.reason": "Detail",
  "mcpSecurity.unauthenticated": "Keine Sitzung",
  "mcpSecurity.admission": "Vor der Anmeldung abgewiesen",
  "mcpSecurity.target": "Ziel {target}",
  "mcpSecurity.revokeTitle": "MCP-Zugriff dieses Tabs entziehen?",
  "mcpSecurity.revokeBody": "„{tab}“ verliert {app}s Werkzeuge endgültig: Sein Agent wird ab jetzt abgewiesen, und nur ein erneutes Öffnen des Tabs vergibt ein neues Token.",
  "mcpSecurity.reviewScope": "Sitzungszugriff: {calendars} Kalender, {projects} Projekte; Aufrufer: {caller}",
