  "rootReview.icsImport": "Kalenderdatei",
  "rootReview.icsImportHelp": "Ein Agent hat diese Kalenderdatei geschickt. Beim Import landen ihre Einträge in einem neuen Kalender \"{name}\"; ohne deine Zustimmung wird nichts importiert.",
  "rootReview.outbound": "Wird an {name} übertragen. Der Server kann Teilnehmer benachrichtigen.",
  "rootReview.conflict": "Dieser Eintrag wurde geändert, seit der Agent ihn gelesen hat. Verwirf den Vorschlag und bitte den Agenten um einen neuen.",
  "rootReview.details": "Änderungen anzeigen",
  "rootReview.reordered": "Und {count} Karten neu sortiert",
  "rootReview.field": "Feld",
  "rootReview.before": "Vorher",
  "rootReview.after": "Nachher",
  "rootReview.delete": "Löschen",
  "rootReview.update": "Ändern",
  "rootReview.create": "Erstellen",
  "rootReview.setting": "Schreibzugriffe von Root-Agenten prüfen",
  "rootReview.levelAll": "Alle Schreibzugriffe (Standard)",
  "rootReview.levelDestructive": "Destruktive Zugriffe; andere Änderungen mit Rückgängig-Funktion",
  "rootReview.levelOff": "Aus — Änderungen sofort anwenden",
  "rootReview.settingHelp": "Kalender- und Board-Vorschläge in der Root-Konsole prüfen. Gilt sofort für nachfolgende Werkzeugaufrufe. Bestehende Vorschläge benötigen weiterhin eine Entscheidung. Dies schützt Schreibzugriffe; Agenten können gelesene Daten weiterhin weitergeben.",
  "settings.rootMcp": "{app}s Werkzeuge (MCP) für Agenten der Root-Konsole",
  "settings.rootMcpHelp": "Agenten der Root-Konsole (Strg+Umschalt+R) mit dem MCP-Chip im Menü „Modelle & Agenten“ erhalten {app}s eigene Werkzeuge: Projekte, Kalender und Aufgabenboard. Aus: Neue Agenten erhalten nichts, bereits laufende werden abgewiesen – ohne Neustart. Projekt-Agenten erhalten sie nie.",
  "settings.rootMcpLocalOnly": "Nur lokale Modelle erhalten diese Werkzeuge",
  "settings.rootMcpLocalOnlyHelp": "Beschränkt {app}s Werkzeuge auf Tabs mit lokalem Modell (die mit dem MCP-Chip im Menü „Modelle & Agenten“). Claude, Codex und alle anderen Cloud-Agenten erhalten nichts, bereits laufende werden ohne Neustart abgewiesen – so erreichen Kalender und Board über diese Werkzeuge nie ein gehostetes Modell.",
  "settings.rootMcpMail": "Agenten erhalten {app}s E-Mail-Werkzeuge",
  "settings.rootMcpMailLocalOnly": "Nur lokale Modelle erhalten die E-Mail-Werkzeuge",
  "settings.rootMcpMailLocalOnlyHelp": "Beschränkt die E-Mail-Werkzeuge auf Tabs mit lokalen Modellen (die mit dem MCP-Chip im Menü „Modelle & Agenten“); Cloud-Agenten behalten Kalender-, Board- und Projektwerkzeuge. Claude, Codex und jedem anderen Cloud-Agenten wird kein E-Mail-Werkzeug angeboten, bereits laufende verlieren sie ohne Neustart, und ein abgeschotteter Lese-Agent wird abgewiesen – so erreicht kein Entwurf und keine Nachricht über diese Werkzeuge ein gehostetes Modell.",
  "settings.rootMcpMailLocalRead": "Lokale Modelle dürfen freigegebene E-Mails lesen",
  "settings.rootMcpMailLocalReadHelp": "Erlaubt einem Tab mit lokalem Modell (die mit dem MCP-Chip im Menü „Modelle & Agenten“), E-Mails der Konten zu lesen, die du Agenten geöffnet hast – nur die Nachrichten, die du freigegeben hast, auch wenn ein Konto ganz geöffnet ist. Lesen wird abgewiesen, sofern der Ollama-Host, mit dem der Tab geöffnet wurde, nicht dieser Rechner ist: Geprüft wird gegen diesen beim Start des Tabs festgehaltenen Host, nicht gegen die aktuelle Einstellung, damit die E-Mails dort bleiben, wo das Modell läuft. Ein solcher Tab hat nur {app}s Werkzeuge, keine Shell und kein Web; hat er E-Mails gelesen, wartet jede Kalender- oder Board-Änderung auf deine Freigabe – in diesem Tab und in jedem späteren Lauf davon –, und seine Entwürfe sind als von einem E-Mail-lesenden Agenten geschrieben markiert. Er sendet nie. Eine präparierte E-Mail kann trotzdem steuern, was das Modell schreibt – lies seine Entwürfe und Vorschläge, bevor du sie annimmst.",
  "settings.rootMcpMailHelp": "Standardmäßig aus und getrennt vom Schalter darüber: {app}s Werkzeuge einzuschalten bringt nie E-Mail mit. Eingeschaltet kann ein Root-Agent E-Mail-Entwürfe schreiben (nie senden, und nie lesen, außer der Schalter für lokale Modelle unten erlaubt einem lokalen Modell die freigegebenen E-Mails), und ein abgeschotteter Lese-Agent in einem VM-Projekt „E-Mail-Leser“ kann die Konten lesen, die du ihm geöffnet hast. Ausgeschaltet wird kein E-Mail-Werkzeug angeboten, bereits laufende Agenten werden ohne Neustart abgewiesen, und die Schalter pro Konto bewirken nichts.",
  "settings.headlessRemote": "Verbindungen im Hintergrund",
  "settings.persistLocal": "Persistente lokale Sitzungen (tmux)",
  "settings.remoteFeatures": "Remote-Funktionen",
  "settings.vm": "Virtuelle Maschinen",
