  "settings.vmReady": "QEMU und die übrigen VM-Voraussetzungen sind bereit.",
  "settings.vmCheckFailed": "VM-Voraussetzungen konnten nicht geprüft werden. Öffne diese Seite erneut.",
  "settings.vpnEnabled": "OpenVPN-Tunnelsteuerung",
  "settings.machinesEnabled": "Globale Remote-Maschinen",
  "settings.energySaver": "Energiesparen",
  "settings.fastMode": "Schneller Modus",
  "energy.off": "Aus",
  "energy.battery": "Im Akkubetrieb",
  "energy.always": "Immer",
  "settings.debug": "Debug-Modus",
  "settings.experimental": "Experimentell",
  "settings.terminalWebgl": "WebGL-Terminal-Renderer",
  "settings.terminalWebglHelp": "Zeichnet Terminals mit einem GPU-Glyphen-Atlas (die schnelle Stufe — wie in VS Code) statt mit dem Canvas-Renderer. Nutzt denselben GPU-Treiberpfad, der auf manchen Maschinen defekt ist: Bei Flackern, fehlendem Text oder einem abgestürzten Fenster wieder ausschalten. Ein Terminal, dessen WebGL-Kontext ausfällt, fällt von selbst auf den Canvas-Renderer zurück. Wirkt sofort auch auf bereits offene Terminals.",
  "settings.mdGraph": "Markdown-Linkgraph",
  "settings.mdGraphHelp": "Fügt dem Markdown-Viewer einen Graph-Modus hinzu: eine klickbare Karte der Dateien, die dieses Dokument verlinkt, Link für Link ab der betrachteten Datei aufgebaut (Markdown-Ziele werden weiterverfolgt, alle anderen Dateien sind Blätter). Ein Klick auf einen Knoten öffnet die Datei; die Karte wird pro Ansicht einmal gebaut, nie im Hintergrund.",
  "settings.pythonRunDebug": "Python Ausführen/Debuggen im Code-Viewer",
  "settings.mailClient": "Mail-Client",
  "settings.mailClientHelp": "Setzt eine Mail-Schaltfläche in die Kopfzeile, die einen IMAP/SMTP-Client mit eigenem lokalem Index als Überlagerung über dem ganzen Fenster öffnet — Mail gehört Ihnen, nicht einem Projekt, deshalb gibt es keinen Mail-Tab. Ein roter Punkt darauf zählt die ungelesenen Nachrichten im Posteingang. Wird dies ausgeschaltet, verschwindet die Schaltfläche; Konten und heruntergeladene Mails bleiben unangetastet.",
  "settings.mailCheckInterval": "Nach neuer Post sehen",
  "settings.mailCheckIntervalHelp": "Wie oft {app} Ihre Konten selbständig prüft — alle 5 Minuten, sofern Sie nichts anderes wählen. Auf „Nie“ gestellt wird Mail nur abgerufen, wenn Sie „Mail abrufen“ drücken; der rote Punkt kann dann auch nur unmittelbar danach erscheinen.",
  "settings.mailCheckNever": "Nie — nur auf Anforderung",
  "settings.mailCheckMinutes": "Alle {count} Minuten",
  "settings.webBrowser": "Browser in der App",
  "settings.webBrowserHelp1": "Fügt einen Browser-Tab hinzu. Seiten öffnen im",
  "settings.webBrowserHelp2": "– nur Text und Bilder, ohne Skripte, Formulare und Anmeldung. Eine echte Seite läuft in einem separaten Fenster, einen bewussten Klick entfernt, und nur dort, wo dieser Build eines bereitstellen kann.",
  "settings.browser": "Browser",
  "settings.browserHome": "Startadresse",
  "settings.browserHomePlaceholder": "(Startseite)",
  "settings.browserHomeHelp": "Wo ein neuer Browser-Tab öffnet. Bleibt das Feld leer, öffnet ein neuer Tab auf seiner Startseite – er geht erst online, wenn du es verlangst.",
  "settings.browserSearch": "Suchadresse",
  "settings.browserSearchHelp": "Was die Adresszeile mit Text macht, der keine Webadresse ist – %s wird durch das Eingetippte ersetzt. Leere das Feld, und solcher Text wird schlicht abgelehnt, statt an eine Suchmaschine zu gehen.",
  "settings.browserLinkTarget": "Links öffnen in",
  "settings.browserLinkTargetExternal": "Deinem eigenen Browser",
  "settings.browserLinkTargetInApp": "{app}s Lesemodus",
  "settings.browserLinkTargetAsk": "Jedes Mal fragen",
  "settings.browserLinkTargetHelp": "Der eigene Browser ist die Voreinstellung: dort liegen deine Anmeldungen, deine Erweiterungen und dein Passwortmanager. Links aus E-Mails, Terminal-Ausgaben oder Antworten eines Agenten öffnen immer im Lesemodus, egal was hier steht – dort hat der Inhalt das Ziel für dich gewählt. Deine Wahl wird gespeichert, aber {app}s eigene Link-Oberflächen fragen sie noch nicht ab: vorerst geht jeder Link weiterhin in deinen eigenen Browser.",
  "settings.browserRestoreNavigate": "Offene Seiten beim Start neu laden",
  "settings.browserRestoreNavigateHelp": "Standardmäßig aus. Bleibt es aus, zeigt ein wiederhergestellter Browser-Tab die Adresse und wartet auf dich – ein wiederhergestelltes Fenster ist keine Aufforderung, online zu gehen.",
  "settings.browserLivePages": "Live-Seiten erlauben",
  "settings.browserLivePagesHelp": "Standardmäßig aus, auch in Debug-Builds. Der Lesemodus zeigt den Text einer Seite ganz ohne Skripte. Eine Live-Seite führt die echte Webseite in einem eigenen, gehärteten Fenster aus – damit kann sie auch Dienste erreichen, die auf diesem Rechner laufen, etwa einen lokalen Modellserver oder ein Notebook, und das lässt sich innerhalb von {app} nicht verhindern. Schalte das nur ein, wenn du es brauchst.",
  "settings.resourceMonitor": "Ressourcenmonitor",
  "settings.showCpu": "CPU-Auslastung anzeigen",
  "settings.showRam": "RAM-Auslastung anzeigen",
  "settings.showGpu": "GPU-Auslastung anzeigen",

