  "settings.calendar": "Kalender",
  "settings.calendarGlobalApp": "Kalender in der Kopfzeile",
  "settings.calendarGlobalAppHelp": "Fügt der Kopfzeile eine Kalender-Schaltfläche hinzu, die den Kalender als Überlagerung über dem ganzen Fenster öffnet — egal, wo Sie gerade sind: Ihr Kalender gehört nicht zu dem Projekt, das Sie zufällig ansehen. Ein roter Punkt darauf zählt die heute noch verbleibenden Termine und leert sich im Lauf des Tages von selbst.",
