  "settings.mobile": "Mobil",
  "settings.mobileIndicator": "Mobile-Verbindung in der Kopfzeile anzeigen",
  "settings.mobileIndicatorHelp":
    "Zeigt den Status des {app}-Mobile-Hosts und Schnellzugriffe zum Neuverbinden neben der Akkuanzeige.",

  "mobile.title": "{app} Mobile",
  "mobile.mailWrites": "Mail vom Telefon",
  "mobile.mailRead": "Mail auf dem Telefon lesen",
  "mobile.mailReadHelp": "Ein gekoppeltes Telefon darf deine Mailkonten und Ordner auflisten und Nachrichten öffnen. Ausgeschaltet wird die Mail-Ansicht des Telefons vollständig abgelehnt — Markieren und Antworten eingeschlossen.",
  "mobile.mailActions": "Vom Telefon als gelesen markieren und markieren",
  "mobile.mailActionsHelp": "Ein gekoppeltes Telefon darf eine Nachricht als gelesen oder ungelesen markieren und den Stern setzen oder entfernen. Der Desktop setzt das Flag über seine eigene Mail-Sitzung und antwortet mit der aktualisierten Liste. Löschen und Verschieben bleiben auf dem Desktop, wo sie rückgängig gemacht werden können.",
  "mobile.mailReply": "Vom Telefon antworten",
  "mobile.mailReplyHelp": "Ein gekoppeltes Telefon darf eine Nur-Text-Antwort auf eine Nachricht senden, die es gerade liest. Das Telefon liefert nur den Text: Empfänger, Betreff und Verkettung stammen aus der Originalnachricht, sodass ein Telefon nur Personen antworten kann, die dir bereits geschrieben haben. Keine neuen Mails, keine Anhänge, kein Signieren oder Verschlüsseln. Ein verlorenes Telefon kann mit dieser Einstellung in deinem Namen Mails senden, bis du es widerrufst.",
  "mobile.settingsHelp": "Privater Zugriff auf Projekt-Terminals über Tailscale Serve. Der Host lauscht nur auf Loopback, und jeder Browser muss gekoppelt werden. Er läuft, solange {app} läuft: mit der App gestartet, beim Beenden der App gestoppt.",
  "mobile.healthOffTitle": "Mobile ist aus",
  "mobile.healthOffDetail": "Derzeit ist kein {app}-Mobile-Host veröffentlicht.",
  "mobile.healthStoppedTitle": "Host ist gestoppt",
  "mobile.healthStoppedDetail": "Mobile ist in den Einstellungen aktiviert, aber nicht in Betrieb; starte es erst, nachdem du das private Serve-Mapping geprüft hast.",
  "mobile.healthServeTitle": "Serve-Mapping braucht Aufmerksamkeit",
  "mobile.healthServeDetail": "{app} kann sein exaktes privates Loopback-HTTPS-Mapping derzeit nicht verifizieren.",
  "mobile.healthGoodTitle": "Private Veröffentlichung verifiziert",
  "mobile.healthGoodDetail": "Der Host ist nur über Loopback erreichbar, und die konfigurierte Tailscale-Serve-Route ist privates HTTPS.",
  "mobile.lockdownNow": "Jetzt sperren",
  "mobile.lockdownTitle": "Alle gekoppelten Geräte widerrufen und den Host stoppen",
  "mobile.lockdownTitleStopped": "Der Host ist bereits gestoppt",
  "mobile.lockdownConfirm": "{app} Mobile jetzt sperren? Das widerruft sofort jedes gekoppelte Telefon, trennt dessen Terminal-Verbindungen und stoppt den Mobile-Host. Jedes Telefon muss sich neu koppeln.",
  "mobile.lockdownPartial": "Die Sperrung wurde nur teilweise abgeschlossen: {reason}",
  "mobile.scopeHelp": "Geprüft wird nur {app}s Veröffentlichungsform — nicht deine Tailnet-ACLs, die Konto-MFA, Tailnet Lock oder die Bildschirmsperre des Telefons. Konfiguriere diese in Tailscale und auf dem Telefon.",
  "mobile.phoneInstallTitle": "{app} Mobile auf deinem Telefon installieren",
  "mobile.phoneInstallHelp": "Verifiziert das private Tailscale-Serve-Mapping und zeigt dann die vertrauenswürdige URL und einen scanbaren QR-Code in einem Root-Terminal. Es aktiviert Mobile nicht und ändert deine Tailscale-Konfiguration nicht.",
  "mobile.phoneInstallButton": "Installations-QR anzeigen",
  "mobile.phoneInstallTab": "{app} Mobile auf dem Telefon installieren",
  "mobile.phoneInstallToast": "Die Telefon-Installationsübergabe läuft im Root-Terminal",
  "mobile.phoneInstallError": "Die Telefon-Installationsübergabe konnte nicht geöffnet werden: {reason}",
  "mobile.guideSummary": "Tailscale Serve einrichten",
  "mobile.windowsTerminalsNote": "Unter Windows kann das Telefon die Terminals und Agenten-Tabs dieses Computers nicht öffnen: Sie werden über tmux angebunden, das es unter Windows nicht gibt.",
  "mobile.guideIntro": "Erledige dies auf diesem Computer, bevor du {app} Mobile einschaltest. Installiere Tailscale und melde dich hier an; installiere es dann auf dem Telefon oder Tablet, das Mobile nutzen soll, und melde dich dort im selben Tailnet an.",
  "mobile.guideStep1a": "Prüfe in einem Terminal auf diesem Computer die bestehende Veröffentlichung mit",
  "mobile.guideStep1b": ". {app} Mobile braucht den HTTPS-/-Handler (Root); ersetze einen bestehenden Root-Handler also nur, wenn du diesen Dienst wirklich verschieben willst.",
  "mobile.guideStep2a": "Konfiguriere den privaten, dauerhaften Reverse-Proxy. Nutze Serve — nicht Funnel:",
  "mobile.guideStep2b": "Falls Tailscale um Bestätigung oder HTTPS-Einrichtung bittet, schließe das im geöffneten Browser ab.",
  "mobile.guideStep3a": "Führe",
  "mobile.guideStep3b": "erneut aus und nutze dann",
  "mobile.guideStep3c": "weiter unten. {app} übernimmt Computernamen, Loopback-Port und verifizierten Origin aus dem privaten Root-Mapping.",
  "mobile.guideStep4a": "Schalte {app} Mobile ein. {app} verifiziert, dass der Root-Handler des Origins exakt weiterleitet auf",
  "mobile.guideStep4b": "; nutze",
  "mobile.guideStep4c": "falls du Tailscale in einem anderen Terminal geändert hast.",
  "mobile.guideStep5": "Aktiviere die lokalen Projekte, die du freigeben willst, erstelle einen Kopplungscode, öffne dann den verifizierten Origin auf dem Telefon oder Tablet und gib den Code ein.",
  "mobile.guideOutro": "Die Adresse ist nur für Geräte erreichbar, die dein Tailnet zulässt, und Mobile verlangt zusätzlich seine eigene Gerätekopplung. Nutze kein Tailscale Funnel: Es macht den Dienst öffentlich, und {app} verweigert dann den Start.",
  "mobile.setUpInTerminal": "Im Terminal einrichten",
  "mobile.setUpInTerminalHelp": "Öffnet nach Bestätigung ein Root-Terminal und führt den obigen Befehl aus.",
  "mobile.setUpConfirm": "Dies öffnet ein Root-Terminal und führt aus:\n\n{command}\n\nEs aktualisiert den HTTPS-Root-Handler von Tailscale Serve und kann einen derzeit unter / eingehängten Dienst ersetzen. Fortfahren?",
