  "mobile.stayAfterQuitHeader": "Wenn {app} geschlossen ist",
  "mobile.stayAfterQuit": "Weiterlaufen, wenn {app} geschlossen ist",
  "mobile.stayAfterQuitHelp": "Beim Beenden von {app} läuft der Mobile-Host weiter: Das Telefon kann weiterhin Tabs sehen und starten, geplante Prompts und Kalender-Erinnerungen gehen weiter raus. Offene Tabs werden beim Beenden trotzdem geschlossen. Aus: Beenden stoppt auch den Mobile-Host.",
  "mobile.rootAccessHeader": "Root-Konsole",
  "mobile.rootAccess": "Root-Konsole auf dem Telefon",
  "mobile.rootAccessHelp": "Ein gekoppeltes Telefon darf die Tabs der Root-Konsole öffnen und dort Shells und Agenten starten. Ein vom Telefon gestarteter Root-Agent erhält dieselben MCP-Werkzeuge wie ein hier gestarteter. Seine Vorschläge zu genehmigen, abzulehnen oder rückgängig zu machen bleibt diesem Desktop vorbehalten; das Telefon sieht nur, wie viele Vorschläge warten.",
