  "mobile.project.fileTab.root": "Projektordner",
  "mobile.open.hostOutdated": "Der Mobil-Host des Desktops ist zu alt, um diese Datei im Browser zu öffnen. Öffne am Desktop das Mobil-Menü und klicke auf Neu verbinden, dann hier zum Aktualisieren nach unten ziehen.",
  "mobile.tunnel.slow": "Das dauert.",
  "mobile.tunnel.try": "Versuche der Reihe nach:",
  "mobile.tunnel.step.open": "Öffne Tailscale auf diesem Handy und prüfe, ob es verbunden ist.",
  "mobile.tunnel.step.forceStop": "Schon verbunden? Beende es erzwungen: Einstellungen → Apps → Tailscale → „Beenden erzwingen“ (Samsung: „Stopp erzwingen“), dann öffne es wieder. Nach einem Netzwechsel kann es „verbunden“ anzeigen und trotzdem nichts durchlassen; Aus- und Einschalten hilft dagegen nicht.",
  "mobile.tunnel.step.airplane": "Immer noch nichts? Schalte den Flugmodus fünf Sekunden ein, dann wieder aus, und tippe auf „Erneut versuchen“.",
  "mobile.tunnel.step.desktop": "Immer noch nichts? Dann schläft dein Desktop wahrscheinlich oder ist aus.",
  "mobile.tunnel.prevent": "Damit es seltener passiert: stelle den Akku von Tailscale auf „Uneingeschränkt“ (Einstellungen → Apps → Tailscale → Akku) und schalte „Durchgehend aktives VPN“ dafür ein (in den Einstellungen nach „VPN“ suchen, dann auf das Zahnrad neben Tailscale tippen).",
  "mobile.tunnel.openApp": "Tailscale öffnen",
  "mobile.files.openFolder": "Ordner {name} öffnen",
  "mobile.files.openFile": "{name} öffnen",
  "mobile.projectFiles": "Projektdateien auf dem Telefon",
  "mobile.noShells": "Keine Shells auf dem Telefon",
  "mobile.noShellsHelp": "Ein gekoppeltes Telefon sieht und öffnet nur Agenten-Tabs. Shell-Tabs fehlen in seinen Listen, und es kann keine starten; ausgeschaltet darf es sich mit Shells verbinden und sie öffnen – sie laufen als du, ohne etwas dazwischen.",
  "mobile.localModelsGate": "Lokale Modelle vom Telefon",
  "mobile.localModelsGateHelp": "Ein gekoppeltes Telefon darf die hier installierten Ollama-Modelle sehen und laden oder entladen. Es kann keine Modelle herunterladen, aktualisieren oder löschen, und es startet Ollama nur, ohne nach einem Passwort zu fragen. Wird ein einzelnes Modell geladen, wird es wie hier zum Modell für jede Rolle.",
