  "mobile.boxAccess": "Box-Zugriff",
  "mobile.boxAccessHelp": "Eine Box erscheint auf dem Telefon als eigener Eintrag mit den darin geöffneten Terminals — im Box-Ordner oder im Ordner eines lokalen Mitglieds. Mitglieder behalten ihre eigenen Schalter; ein Container-, VM- oder Remote-Mitglied trägt nichts bei.",
