  "mobile.indDisconnectHint": "Entkoppelt dieses Gerät und meldet es innerhalb von Sekunden ab. Zum Zurückkommen braucht es einen neuen Kopplungscode.",
  "mobile.indDisconnectError": "{name} konnte nicht getrennt werden: {reason}",
