  "mobile.setupTitle": "{app} Mobile einrichten",
  "mobile.indDeviceAccess": "Zugriff",
  "mobile.indDeviceAccessHint": "Festlegen, welche Bereiche und Projekte {name} sieht",
  "mobile.setupIntro": "{app} Mobile bringt die Projekte, Terminals und Agenten dieses Computers auf dein Telefon. Es läuft über dein eigenes privates Tailscale-Netz: Nichts wird im Internet veröffentlicht, und das Telefon muss zusätzlich gekoppelt werden.",
  "mobile.setupStep1Title": "Tailscale auf diesem Computer installieren",
  "mobile.setupStep1Body": "Installiere Tailscale hier und melde dich an. Es trägt die Verbindung des Telefons — {app} selbst lauscht nur auf Loopback.",
  "mobile.setupStep2Title": "Tailscale auf dem Telefon installieren",
  "mobile.setupStep2Body": "Installiere die Tailscale-App auf dem Telefon oder Tablet und melde dich im selben Tailnet an wie auf diesem Computer.",
  "mobile.setupStep3Title": "{app} privat veröffentlichen",
  "mobile.setupStep3Body": "Richte Tailscale Serve auf {app}s Loopback-Port. Nutze Serve, niemals Funnel: Funnel macht den Dienst öffentlich, und {app} verweigert dann den Start. Wenn Tailscale eine Bestätigung oder HTTPS-Einrichtung verlangt, schließe sie im geöffneten Browser ab.",
  "mobile.setupStep4Title": "{app} Mobile einschalten",
  "mobile.setupStep4Body": "Drücke in Einstellungen → Mobil auf „Tailscale-Serve-Einstellungen erkennen“, prüfe Computername, Port und Origin, und schalte {app} Mobile dann ein. {app} verifiziert die Zuordnung, bevor der Host startet.",
  "mobile.setupStep5Title": "Auswählen, was das Telefon öffnen darf",
  "mobile.setupStep5Body": "Aktiviere unter „Projektzugriff“ in denselben Einstellungen die Projekte und Boxen, die das Telefon öffnen darf. Alles ist aus, bis du es aktivierst.",
  "mobile.setupStep6Title": "Telefon koppeln",
  "mobile.setupStep6Body": "Drücke auf „Installations-QR anzeigen“ und scanne ihn mit dem Telefon, erstelle dann einen Kopplungscode und gib ihn dort ein. Ein Code ist fünf Minuten gültig.",
  "mobile.setupOpenSettings": "Mobile-Einstellungen öffnen",
  "settings.usageStats": "Nutzungsstatistik",
  "settings.pdfMarkup": "PDF-Markierung",
  "settings.pdfMarkupHelp": "Was „Markieren“ im PDF-Viewer an den Agenten sendet. Auf diesem Computer gespeichert; das Handy hat eigene (Start → ⚙ Dieses Gerät → Markierungs-Prompt).",
  "settings.pdfMarkupInstruction": "Markierungs-Prompt",
  "settings.pdfMarkupInstructionHelp": "Steht bei jedem Absenden nach der Datei, der markierten Kopie, den Ebenen und deinen getippten Notizen. Mit „Markierungen direkt umsetzen“ setzt der Agent die Änderungen standardmäßig um und baut das PDF neu; sonst — oder wo kein Rückgängig gehalten werden kann — listet er die Änderungen auf und bearbeitet nichts, bis du es sagst.",
  "settings.pdfMarkupApply": "Prompt für „Änderungen umsetzen“",
  "settings.pdfMarkupApplyHelp": "Wird mit der Schaltfläche „Änderungen umsetzen“ gesendet, sobald der Agent aufgelistet hat, was deine Markierungen verlangen.",
  "settings.pdfMarkupAutoReload": "PDF bei Änderung unter deinen Markierungen neu laden",
  "settings.pdfMarkupAutoReloadHelp": "Baut der Agent ein PDF neu, das du gerade markierst, erscheinen die neuen Seiten von selbst unter deinen Markierungen. Aus: Die Markierungsleiste bietet stattdessen „PDF neu laden“ an.",
  "settings.pdfMarkupSubagents": "Jedes Absenden an einen neuen Subagenten geben",
  "settings.pdfMarkupSubagentsHelp": "Jedes Absenden bittet den Agenten, die Runde an einen neuen eigenen Subagenten zu geben und sofort wieder frei zu sein, damit die nächste Runde ohne Warten hinausgeht — Runden laufen nebeneinander. Für Agenten, die Subagenten starten können (Claude Code); einer, der das nicht kann, erledigt die Runde selbst.",
  "settings.pdfMarkupDirect": "Markierungen direkt umsetzen",
  "settings.pdfMarkupDirectHelp": "Beim Absenden setzt der Agent die Änderungen sofort um; ist er fertig, setzt Rückgängig jede Datei zurück, die die Runde geändert hat — und lehnt ab, statt zu überschreiben, was sich seitdem geändert hat. Wo kein Rückgängig gehalten werden kann (kein Git-Repository, zu viele nicht verfolgte Dateien, …) oder wenn das aus ist, listet der Agent die Änderungen zuerst auf, und „Änderungen umsetzen“ lässt ihn sie vornehmen.",
  "settings.pdfMarkupReset": "Standard verwenden",
  "markup.ask.label": "Fragen zu deinen Markierungen",
  "markup.ask.help": "Wie oft der Agent nachfragt, bevor er die Änderungen auflistet. Wird bei jedem Senden nach dem Markup-Prompt angehängt.",
  "markup.ask.stop0": "Immer fragen",
  "markup.ask.stop1": "Oft fragen",
  "markup.ask.stop2": "Bei Unklarheit fragen",
  "markup.ask.stop3": "Selten fragen",
  "markup.ask.stop4": "Nie fragen",
  "markup.ask.hint0": "Eine Frage zu jeder Markierung, bevor sie als Änderung zählt.",
  "markup.ask.hint1": "Fragt, sobald eine Markierung irgendeine Wahl lässt.",
  "markup.ask.hint2": "Fragt nur bei unlesbaren Markierungen oder echten Wahlmöglichkeiten; sonst nimmt er die naheliegende Lesart.",
  "markup.ask.hint3": "Fragt nur, wenn er eine Markierung ohne dich gar nicht umsetzen kann.",
  "markup.ask.hint4": "Entscheidet jede unklare Markierung selbst und listet auf, was er entschieden hat.",
  "settings.dailyRecap": "Zusammenfassung zu Beginn jedes Tages anzeigen",
  "settings.openUsageStats": "Nutzungsstatistik öffnen",

