  "updates.legacyTitle": "Namen aus der Zeit vor der Umbenennung",
  "updates.legacyHelp": "{app} wurde umbenannt. Was eine ältere Version unter dem alten Namen gespeichert hat, wird übernommen, und jedes Mal, wenn etwas nur noch unter dem alten Namen gefunden wird, wird es hier gezählt. Bleibt diese Liste auf allen deinen Rechnern leer, wird der alte Name nirgends mehr gebraucht.",
