  "updates.restartToApply": "Installiert. Starte {app} neu, um die neue Version zu benutzen.",
  "updates.savedTo": "Gespeichert unter {path}",
  "updates.openReleasePage": "Release-Seite öffnen",
  "updates.installAppimageHelp": "Beim Installieren wird das laufende AppImage ersetzt. Deine Tabs und Terminals bleiben offen — starte {app} neu, wenn es dir passt.",
  "updates.installNsisHelp": "Beim Installieren startet das Windows-Installationsprogramm, das zuerst anbietet, {app} zu schließen.",
  "updates.installDmgHelp": "Beim Installieren wird das Disk-Image geöffnet — zieh {app} von dort nach „Programme“.",
  "updates.installManualHelp": "Dieses {app} wurde über eine Paketverwaltung installiert; der Download bleibt daher dir zum Installieren überlassen.",
  "settings.energyUnavailable": "Energiestatus nicht verfügbar — wird als Netzbetrieb (inaktiv) behandelt.",
  "settings.energyActiveAlways": "Derzeit aktiv — immer an.",
  "settings.energyActiveBattery": "Derzeit aktiv — läuft im Akkubetrieb.",
  "settings.energyOff": "Aus — drosselt nie.",
  "settings.energyInactive": "Inaktiv — im Netzbetrieb.",
  "settings.claudeRemoteHelp1": "Startet Claude-Agenten-Tabs mit",
  "settings.claudeRemoteHelp2": "damit du sie über die Claude-App oder das Web überwachen und steuern kannst. Erfordert eine Claude-Abo-Anmeldung (kein API-Schlüssel); nur Claude unterstützt dies.",
  "settings.headlessRemoteHelp": "Wenn aktiviert (Standard), stellt {app} SSH/OpenVPN-Verbindungen im Hintergrund her und handhabt das Passwort nur vorübergehend. Deaktiviere es, um stattdessen jede Verbindung als interaktives Terminal im {app}-Root zu öffnen — du gibst das Passwort direkt in dieses Terminal ein, und {app} fasst es nie an.",
  "settings.persistLocalHelp1": "Wenn aktiviert (Standard), laufen die Shell- und Python-/Skript-Tabs eines lokalen Projekts in einer tmux-Sitzung auf diesem Rechner, sodass ein langer Lauf weitergeht, falls {app} abstürzt, und der Tab beim Neustart wieder verbunden wird. Das Schließen eines Tabs beendet dennoch dessen Sitzung. Erfordert",
  "settings.persistLocalHelp2": "; Agenten-Tabs sind davon nicht betroffen.",
  "settings.remoteFeaturesHelp": "Beide fügen der Kopfzeile eine rechnerweite Steuerung hinzu: einen OpenVPN-Tunnel (leitet den gesamten Datenverkehr dieses Computers um, solange er aktiv ist) und eine Liste von SSH-Maschinen, die keinem Projekt gehören. Standardmäßig aus; wird beim ersten Start einmal abgefragt.",
  "settings.energyHelp": "Wenn aktiv, drosselt {app}, um Energie zu sparen: Es pausiert das Leerlauf-Drehen des Projekt-Blobs, beruhigt die Status-Leuchten und verlangsamt Hintergrundaktualisierungen. „Im Akkubetrieb“ (Standard) tut dies nur, solange kein Netzstecker steckt.",
  "settings.fastModeHelp": "Lässt die Hilfen weg, die echte Arbeit kosten: Ordnergrößen im Dateibaum, die Git-Punkte auf den Projekt-Pillen, die Hover-Karten, die CPU-/RAM-Anzeige in der Kopfzeile, die Python-Ausführen-Prüfung und UI-Animationen. Nichts wird versteckt und nichts geht ungespeichert verloren — {app} sagt weniger, dafür früher. Lohnt sich bei langsamer Platte, ausgelasteter Maschine oder einem entfernten Projekt über eine dünne Leitung.",
  "settings.experimentalHelp1": "Funktionen, die sich noch verändern. Jede ist standardmäßig aus und",
  "settings.experimentalHelpBold": "im Debug-Modus standardmäßig an",
  "settings.experimentalHelp2": "— wer {app} baut, sieht sie also, ohne diese Liste jedes Mal neu abzuhaken, wenn eine neue hinzukommt. Ein Schalter hier gewinnt immer, in beide Richtungen: Du kannst eine ohne Debug-Modus aktivieren oder eine darin deaktivieren.",
  "settings.experimentalHelp3": "Wird eine Funktion ausgeschaltet, die einen eigenen Tab besitzt (Mail, Browser), schließen sich auch die von ihr geöffneten Tabs — aus heißt weg, nicht nur im Neuer-Tab-Menü versteckt.",
  "settings.pythonRunHelp1": "Gibt einer",
  "settings.pythonRunHelp2": "im Editor geöffneten Datei einen",
  "settings.pythonRunHelp3": "und einen",
  "settings.pythonRunHelp4": "Button und verwandelt ihre Zeilennummern in eine Haltepunkt-Randleiste. Beide öffnen einen Terminal-Tab im Projekt — sie laufen also auf dem Host eines Remote-Projekts und im Container eines containerisierten — und verwenden den eigenen Interpreter des Projekts. Debug ist",
  "settings.pythonRunHelp5": ", vorgeladen mit den Haltepunkten der Randleiste. Standardmäßig aus, weil Run die Datei ausführt. Strg+Klick auf eine Definition ist nicht gesperrt: Es liest nur.",
  "settings.resourceMonitorHelp": "CPU und RAM decken den eigenen Prozessbaum von {app} ab; GPU zeigt den von in Ollama geladenen lokalen Modellen genutzten VRAM. Die Pille erscheint in der Kopfzeile neben dem Timer.",
  "settings.reminderHelp": "Erinnerungen erscheinen als Desktop-Benachrichtigung und als In-App-Popup, das du snoozen kannst. „Tagesraster beginnt um“ legt nur fest, wohin die Tages- und Wochenansicht scrollt — frühere Termine sind weiterhin da, nur oberhalb der Ansicht.",
  "settings.zoomHelp1": "Der Fenster-Zoom skaliert die gesamte {app}-Oberfläche — praktisch bei 4K-/High-DPI-Monitoren. 100 % ist Standard. Der Zoom ist",
  "settings.zoomHelpBold": "pro Fenster",
  "settings.zoomHelp2": ": Dies stellt das Hauptfenster ein, und jedes ausgeklinkte Unterfenster behält seinen eigenen Wert. Strg + / Strg − zoomen das fokussierte Fenster, Strg 0 setzt es zurück.",
  "settings.minSubwindowHelp": "Kleinste Größe, auf die ein Unterfenster durch Ziehen einer Trennlinie verkleinert werden kann. Standardmäßig {px}px, wenn leer gelassen.",
  "settings.workspaceNoParking": "Diese Desktopumgebung kann die Fenster anderer Apps nicht ausblenden, daher bleiben sie beim Projektwechsel sichtbar. Unter X11 blendet {app} die Apps eines Projekts bei KDE Plasma und Cinnamon beim Wechsel aus.",
  "settings.downloadsHelp": "Ordner, die vom Downloads-Abschnitt des Seitenpanels (sein Schalter in der Werkzeugleiste) durchsucht werden, um frisch heruntergeladene Dateien schnell in ein Projekt zu kopieren. Nur lesend — {app} ändert nie den Download-Pfad eines Browsers. Standardmäßig der System-Download-Ordner, wenn leer.",
  "settings.removeFolderTitle": "Diesen Ordner entfernen",
  "settings.dailyRecapHelp": "Eine Zusammenfassung des gerade beendeten Tages: welche Agenten du benutzt hast und wie viel du sie gefragt hast, erstellte/geänderte/gelöschte Dateien, Commits und Zeit pro Projekt. Dies auszuschalten stoppt das Popup, nicht die Zählung — alles bleibt lokal.",

  "shortcuts.captureTitle": "Klicken, dann eine Tastenkombination drücken",
  "shortcuts.pressKeys": "Tasten drücken…",
  "shortcuts.resetTitle": "Auf Standard zurücksetzen",
