  "shortcuts.resetAllTitle": "Alle benutzerdefinierten Kürzel entfernen",
  "shortcuts.conflict": "Auch belegt für: {actions}",
  "shortcuts.help": "Auf ein Tastenkürzel klicken und dann die neue Tastenkombination drücken; × schaltet es ab. Unter Linux nimmt der Panel-Umschalter auch ein einzelnes Antippen von Super.",
  "shortcuts.unbind": "Abschalten",
