  "shortcuts.steeringTitle": "In der {app}-Navigation",
  "shortcuts.steeringHelp": "Die Tasten, auf die die {app}-Navigation hört, sobald {chord} sie eingeschaltet hat. Jede Aktion nimmt bis zu zwei Tasten, ohne Modifikatoren gedrückt; ein Buchstabe kann auf der Projektebene etwas anderes bedeuten als in einem Unterfenster.",

  "steering.legendTitle": "{app}-Navigation",

