  "steering.tabCard.desc": "Führt durch die Karte über dem Terminal des aktiven Tabs — Löschen rückgängig, ein Anmeldelink, ein Update-Hinweis. Escape geht zurück zu den Tabs.",
  "steering.region.header": "Obere Leiste",
