  "steering.menu.label": "Kontextmenü",
  "steering.menu.desc": "Öffnet das Rechtsklick-Menü dessen, worauf die Markierung steht: das aktuelle Projekt, der aktive Tab oder das Element unter dem Cursor. Durchlaufen wie jedes Menü; Escape schließt es.",

  "steering.project.label": "Projekt wechseln",

