  "steering.back.label": "Zurück",

  "steering.back.desc": "Eine Ebene hoch — aus Panel, Overlay oder Menü heraus; was die {app}-Navigation geöffnet hat, schließt sich.",
  "steering.jump.label": "Zu Projekt springen",
  "steering.jump.desc": "Aktiviert die nummerierte Station: 1 ist das Root-Terminal, 2 die erste Projekt-Pille.",
  "steering.focus.label": "Unterfenster wechseln",
  "steering.focus.desc": "Fokus auf das vorherige / nächste Unterfenster (Dokumentreihenfolge, umlaufend).",
  "steering.tabs.label": "Tab wechseln",
  "steering.tabs.desc": "Vorheriger / nächster Tab im fokussierten Unterfenster — bei nur einem Unterfenster wechseln die Pfeile direkt die Tabs.",
  "steering.files.label": "Dateiansicht",
  "steering.files.desc": "Schaltet die angedockte Dateiansicht des fokussierten Unterfensters um.",
  "steering.panels.label": "Panels",
  "steering.panels.desc": "Schaltet die Seitenpanels um.",
  "steering.closeTab.label": "Tab schließen",
  "steering.closeTab.desc": "Schließt den aktiven Tab.",
  "steering.agentClear.label": "Unterhaltung leeren",
  "steering.agentClear.desc": "Tippt /clear in den aktiven Agent-Tab: eine neue Unterhaltung, mit „Leeren rückgängig“ am Tab. Die {app}-Navigation bleibt an.",
  "steering.agentPlan.label": "Plan",
  "steering.agentPlan.desc": "Öffnet das Eingabefeld mit /plan am Anfang der Eingabe des aktiven Agent-Tabs; den Rest schreiben, Enter, und die {app}-Navigation kommt zurück.",
  "steering.agentGoal.label": "Ziel",
  "steering.agentGoal.desc": "Öffnet das Eingabefeld mit /goal am Anfang der Eingabe des aktiven Agent-Tabs; den Rest schreiben, Enter, und die {app}-Navigation kommt zurück.",
  "steering.agentPrompt.label": "Prompt",
  "steering.agentPrompt.desc": "Öffnet ein Textfeld in der Fenstermitte für den aktiven Agent-Tab. Enter sendet (ersetzt einen Entwurf in der Eingabe des Agenten), danach geht die {app}-Navigation weiter; Esc kehrt ohne Senden zurück.",
