  "steering.search.label": "Suchen",
  "steering.search.desc": "In das Suchfeld der Fläche tippen (Filter des +-Menüs, Mail-Suche, …). Esc dort führt zurück in die {app}-Navigation.",
  "steering.jumpProject.label": "Zu Projekt springen",
  "steering.jumpProject.desc": "Namen eines offenen oder inaktiven Projekts tippen und mit Enter hinwechseln; ein inaktives wird aktiviert. Danach geht die {app}-Navigation weiter.",
  "steering.popout.label": "Ausgelagertes Fenster",
  "steering.popout.desc": "Holt das ausgelagerte Unterfenster dieses Projekts nach vorn, um dort zu arbeiten; bei mehreren nimmt jeder Druck das nächste. Die {app}-Navigation endet, sobald das Fenster die Tastatur hat.",
  "steering.exit.label": "Beenden",
