  "steering.legend.label": "Tasten ausblenden",
  "steering.legend.desc": "Klappt diese Tastenliste zu einem runden Symbol unten in der Mitte zusammen; die {app}-Navigation bleibt an. Dieselbe Taste (oder ein Klick auf das Symbol) holt die Liste zurück.",
