  "remoteHosts.help":
    "Der Ordner, in dem ein Connect oder Browse für einen SSH-Host öffnet, statt im Home-Verzeichnis des Hosts. Einmal hier festgelegt, gilt es beim nächsten Verbinden zu diesem Host — für den Ordner-Browser eines neuen Remote-Projekts und beim erneuten Verbinden eines bestehenden.",
