  "agentCron.title": "Geplantes Aufwärmen",
  "agentCron.help":
    "Zu jeder Zeit unten sendet {app} eine einzelne Nachricht „{message}“ im Hintergrund an diesen Agenten — im Einmal-Modus der CLI selbst (claude -p, codex exec, …), ohne Terminal, Tab oder Projekt. Das Kontingent einer Agenten-CLI ist ein Zeitfenster, das mit der ersten Nachricht beginnt — bei Claude fünf Stunden — also legt dies fest, wann das Fenster startet, statt es dem ersten echten Prompt zu überlassen.",
  "agentCron.runningNote":
    "Läuft nur, solange {app} geöffnet ist. Eine Zeit, die bei geschlossener App oder schlafendem Rechner verstreicht, wird für diesen Tag übersprungen und nie nachträglich gesendet — Stunden später zu senden würde das Fenster zum denkbar schlechtesten Zeitpunkt öffnen.",
  "agentCron.enable": "Geplante Aufwärmnachrichten senden",
  "agentCron.globalTimes": "Zeiten",
  "agentCron.globalTimesHelp":
    "Gilt für jeden Agenten unten, der keine eigenen Zeiten nennt.",
