  "agentSchedule.warning": "Wenn ein Prompt fällig wird, wartet {app} bis zu einer Stunde auf einen sicheren Leerlauf. Die Zustellung ersetzt ungesendeten Text im Eingabefeld dieses Agenten, auch wenn der Tab fokussiert ist.",
  "agentSchedule.openOnly": "Die Zustellung übernimmt, was von {app} gerade läuft: ein offenes Fenster oder, bei eingeschaltetem {app} Mobile, dessen Hintergrunddienst, solange kein Fenster offen ist – er startet die Sitzung dieses Agenten vorher neu, falls sie beendet wurde. Verpasste Termine werden vermerkt und wiederkehrende Pläne senden keinen Rückstau auf einmal.",
  "agentSchedule.windowOnlyTimers": "Auto-Weiter, der Aufwärm-Cron und die CalDAV-Synchronisation laufen weiterhin nur aus einem offenen {app}-Fenster. Kalender-Erinnerungen erreichen ein angemeldetes Telefon auch ohne offenes Fenster, genau einmal.",
