  "howToStart.title": "Willkommen bei {app}",
  "howToStart.intro": "{app} hält deine KI-unterstützte Entwicklung in einem Fenster. So legst du los:",
  "howToStart.openFeatureGuide": "Funktionsübersicht öffnen...",
  "howToStart.takeTour": "Tour starten",
