  "pill.containerScopeAllHelp": "Agenten-Tabs, Shells, Skripte und Ausführen/Debuggen im Viewer. Nichts aus diesem Projekt erreicht den Rest deines Rechners.",
  "pill.containerScopeAgents": "Nur Agenten-Tabs",
  "pill.containerScopeAgentsHelp": "Shells, Skripte und Ausführen/Debuggen bleiben auf dem Host, mit deiner Host-Toolchain — eine .venv-, conda- oder pyenv-Umgebung funktioniert wieder, weil ihr Interpreter auf dem Host liegt und nicht im Image.",
  "pill.containerScopeAgentsCaveat": "Der Agent schreibt weiterhin in den Projektordner, ein von ihm geschriebenes Skript ist also einen Ausführen-Klick von deinem ganzen Rechner entfernt. Diesen Schritt kann er nicht selbst gehen — keine Datei im Projekt wird als Startbefehl zurückgelesen — aber lies, was du ausführst. Für Code, den du für bösartig und nicht bloß ungeprüft hältst, ist ein Container die falsche Stufe.",
  "pill.containerAppliedNote": "Wird beim nächsten Containerstart angewendet (Projektaktivierung oder Tab-Erzeugung) — ein laufender Container mit geänderten Einstellungen wird automatisch ersetzt.",
  "pill.buildFromDockerfile": "Aus einem Dockerfile in diesem Projekt bauen",
