  "pill.vmBoot": "VM starten",
  "pill.vmShutdown": "VM herunterfahren",
  "pill.vmRebuildEllipsis": "VM neu aufbauen…",
  "pill.vmRebuildTitle": "Diese VM neu aufbauen?",
  "pill.vmRebuildConfirm": "Die Festplatte der VM wird aus dem Basisimage neu erstellt. Alles in der VM stirbt damit — für ein Projekt ohne Spiegel IST die VM-Festplatte der Arbeitsbaum; nur was zu einem Git-Remote gepusht (oder herausgeladen) wurde, überlebt. Fortfahren?",
  "pill.vmNumbersError": "Speicher, CPUs und Festplatte müssen positive ganze Zahlen sein",
  "pill.vmMemory": "Speicher (MiB)",
  "pill.vmCpus": "CPUs",
  "pill.vmDisk": "Festplatte (GiB, virtuell)",
  "pill.vmKnobsApplyNote": "Ressourcenänderungen gelten ab dem nächsten VM-Start.",
  "pill.vmEgress": "Netzwerkzugang",
  "pill.vmEgressProxy": "Nur Agent-APIs (Allowlist-Proxy)",
  "pill.vmEgressOff": "Keiner (vollständig geschlossen)",
  "pill.vmEgressOpen": "Offen (volles Netzwerk)",
  "pill.vmEgressProxyCaveat": "Die VM erreicht über {app}s Proxy nur die untenstehenden Hosts; alles andere wird blockiert und protokolliert. Ehrliche Grenze: ein Agent kann weiterhin Daten an die erlaubten Endpunkte senden (z. B. in einem Modell-Prompt) — der Proxy verengt den Kanal, schließen kann er ihn nicht. Änderungen am Modus gelten ab dem nächsten Start.",
  "pill.vmEgressOffNote": "Ohne Netzwerkzugang erreicht die VM nichts — Cloud-Agent-Tabs funktionieren nicht; nutzen Sie ein lokales Modell oder reine Build-/Test-Isolation.",
  "pill.vmMailReader": "E-Mail-Leser",
  "pill.vmMailReaderHelp": "Agent-Tabs in dieser VM dürfen die E-Mail-Konten lesen, die Sie für Agenten geöffnet haben, und Entwürfe schreiben. Der Weg nach außen ist eingeengt und protokolliert, nicht versiegelt: Der Agent erreicht weiterhin seinen eigenen Anbieter, der erhält, was er liest. Er kann niemals senden — nur ein Entwurf, den Sie selbst senden, verlässt den Rechner. Gilt ab dem nächsten Start; kein Spiegel, und Dateien, die Sie aus dieser VM herunterladen, können E-Mail-Inhalte enthalten.",
  "pill.vmMailReaderWide": "Ein E-Mail-Leser läuft nur mit Proxy-Netzwerkzugang und der Standard-Freigabeliste — kein GitHub, keine zusätzlichen Hosts. Schalten Sie „E-Mail-Leser“ aus, um das Netzwerk zu erweitern.",
  "pill.vmAllowGithub": "github.com erlauben (Klonen/Pushen)",
  "pill.vmAllowHosts": "Zusätzlich erlaubte Hosts (einer pro Zeile)",
  "pill.vmAllowHostsPlaceholder": "registry.npmjs.org\n.crates.io",
  "pill.vmBlockedCount": "{count} blockierte Verbindung(en) — die VM wollte Hosts außerhalb der Liste erreichen:",
  "pill.pythonInterpMenuTitle": "Die Python-Umgebung, in der die Skripte dieses Projekts laufen und debuggt werden. Standardmäßig automatisch erkannt (venv im Baum, poetry, conda, pyenv); pinne eine, wenn deine Umgebung dort liegt, wo {app} sie nicht erschließen kann.",
  "pill.pythonInterpreterEllipsis": "Python-Interpreter…",
  "pill.autoConnectTitleNonHeadless": "Dieses Projekt beim Start und beim Wechsel dorthin automatisch verbinden. {app} handhabt in diesem Modus keine Passwörter, daher öffnet sich die Anmeldung (und das VPN, falls vorhanden) im Root-Terminal zur Authentifizierung — dann verbindet sich das Projekt von selbst.",
  "pill.autoConnectTitleEligible": "Dieses Projekt beim Start und beim Wechsel dorthin automatisch verbinden. Es fragt nie nach etwas: Es geht direkt hinein, wenn der Host erreichbar ist, und baut das VPN nur auf, wenn nicht.",
  "pill.autoConnectTitleNotEligible": "Speichere zuerst das SSH-Passwort (oder verwende Schlüsselauthentifizierung) — Auto-Connect wird nur angeboten, wenn das Verbinden nichts von dir benötigt.",
  "pill.autoConnectOnLaunch": "Automatisch beim Start verbinden",
  "pill.persistSessionsMenuTitle": "Die Remote-Shell-, Python-/Skript- UND Agenten-Tabs (Claude, Codex, …) dieses Projekts in einer tmux-Sitzung auf dem Host ausführen, sodass ein langer Lauf — oder ein laufender Agent — über einen SSH-Abbruch, Laptop-Schlaf oder {app}-Beenden hinweg weiterläuft und der Tab sich beim erneuten Verbinden wieder verbindet. Ein Agent verbindet sich mit seinem laufenden Prozess; ist die Host-Sitzung weg, wird stattdessen die Konversation fortgesetzt. Das Schließen eines Tabs löst ihn nur ab (die Sitzung läuft weiter und ist in der Sitzungsansicht wieder verbindbar).",
  "pill.persistentSessionsTmux": "Persistente Sitzungen (tmux)",
  "pill.remoteControlMenuTitle":
    "Ob die Claude-Agenten-Tabs dieses Projekts über die Claude-App oder das Web überwacht/gesteuert werden können. Klicken zum Durchschalten: globale Einstellung verwenden → erzwungen aus → erzwungen ein.",
  "pill.remoteControlInherit": "Fernsteuerung (Standard)",
  "pill.remoteControlOff": "Fernsteuerung: aus",
  "pill.remoteControlOn": "Fernsteuerung: ein",
  "pill.remoteMachinesMenuTitle": "Zusätzliche Maschinen hinzufügen und verwalten, auf denen dieses Projekt läuft. Sie führen denselben Code aus (in Einweg-Sync gehalten) als schreibgeschützte Experiment-Worker; ihre Ausgaben bleiben auf jeder Maschine.",
  "pill.remoteMachinesCount": "Remote-Maschinen… ({count})",
  "pill.remoteMachinesEllipsis": "Remote-Maschinen…",
  "pill.closeAllTabs": "Alle Tabs und Fenster schließen",
  "pill.adoptFolderLayout": "Im Ordner gespeichertes Layout wiederherstellen…",
  "pill.adoptFolderLayoutOk": "{count} Tab(s) aus dem Ordner wiederhergestellt.",
  "pill.adoptFolderLayoutNone": "Dieser Ordner enthält kein gespeichertes Layout.",
  "pill.dangerZone": "Gefahrenzone",
  "pill.detachSshMenuTitle": "Dies wieder in ein lokales Projekt verwandeln. Die lokale Arbeitskopie bleibt, wo sie ist, und die Dateien des Remote-Hosts bleiben unberührt — aber die Kopplung wird aufgehoben: Git-Sync stoppt, und die Auto-Sync-Auswahl, die du für diesen Host eingerichtet hast, wird verworfen.",
  "pill.detachSshEllipsis": "SSH-Host trennen…",
  "pill.removeGitMenuTitle": "Das .git-Verzeichnis dieses Projekts und den gesamten Versionskontrollverlauf löschen (kann nicht rückgängig gemacht werden)",
  "pill.removeGitHistoryEllipsis": "Git & Verlauf entfernen…",
  "pill.deleteProjectMenuTitle": "Dieses Projekt trennen und in das {app}-Archiv verschieben. Später über die Einstellungen wiederherstellen oder endgültig löschen. Die Dateien eines Remote-Hosts werden nie angefasst.",
  "pill.deleteProjectEllipsis": "Projekt löschen…",
  "pill.forgetProjectMenuTitle": "Dieses Projekt aus {app} entfernen, den Ordner aber genau dort lassen, wo er ist. Im Ordner wird nichts angefasst — nur {app}s eigene Einträge zum Projekt werden entfernt. Der Ordner kann danach erneut importiert werden.",
  "pill.forgetProjectEllipsis": "Aus {app} entfernen…",
  "pill.forgetProjectTitle": "{name} aus {app} entfernen",
  "pill.forgetDescPre": "Dies nimmt",
  "pill.forgetDescMid": "aus der Projektliste und verwirft {app}s Einträge dazu (Tab-Layout, Sitzungen, Zeitverlauf). Der Ordner wird",
  "pill.forgetDescPost": "angefasst: project.json, Gerüstdateien und alles andere bleiben auf der Platte, und der Ordner kann erneut importiert werden.",
  "pill.forgetRemoteNote": "Der Remote-Host und der lokale Spiegel bleiben, wie sie sind.",
