  "remoteMachines.saveTitleTerminal": "Eine Terminal-Anmeldung sieht {app} nie, daher wird nichts Neues gespeichert — und auch nichts gelöscht. Ein gespeichertes Passwort bleibt unverändert; im eigenen Connect-Menü der Maschine kannst du es ändern.",
