  "machines.utilGpuTitle": "GPU-Auslastung: {pct} % (am stärksten ausgelastete NVIDIA-GPU, aktualisiert, solange dieses Menü offen ist). Angezeigt, weil diese Maschine im Modus „Detailliert“ gelesen wird.",
