  "machines.autoConnectTitle": "Verbindet diese Maschine still beim Start von {app} und immer, wenn ein VPN-Tunnel aufgebaut wird. Fragt nie nach — verbindet sich nur, wenn der Host ohne Passwort erreichbar ist.",
  "machines.autoConnectAddTitle": "Verbindet diese Maschine still beim Start von {app} und immer, wenn ein VPN-Tunnel aufgebaut wird. Fragt nie nach — verbindet sich nur, wenn der Host ohne Passwort erreichbar ist, daher bleibt eine aktivierte Maschine, die sich nicht still verbinden kann, einfach aus.",
  "machines.autoBlockedHpc": "— aus, solange als HPC markiert",
  "machines.autoBlockedHpcAdd": "— aus für einen HPC-Cluster",
  "machines.hpcToggleLabel": "HPC-Cluster (Login-Knoten)",
  "machines.hpcToggleTitle": "Markiert diese Maschine als geteilten Cluster-Login-Knoten. {app} liest sie dann sparsam (keine Namen oder Befehle anderer Nutzer), scannt oder vermisst nie von sich aus ihr Dateisystem, führt nie Datei- oder Git-Synchronisierung im Hintergrund gegen sie aus, prüft oder verbindet sich nie mit ihr, außer du fragst danach, und fragt nach, bevor irgendetwas in ihrer Login-Knoten-Shell läuft. Das Markieren löscht auch ihr Verbinden-beim-Start.",
  "machines.hpcAddTitle": "Markiert diese Maschine als geteilten Cluster-Login-Knoten. {app} liest sie dann sparsam (nie Namen oder Befehlszeilen anderer Nutzer), scannt oder vermisst nie von sich aus ihr Dateisystem, führt keine Datei- oder Git-Synchronisierung im Hintergrund gegen sie aus, prüft oder verbindet sich nie mit ihr, außer du fragst danach, und fragt nach, bevor irgendetwas in ihrer Login-Knoten-Shell läuft.",
  "machines.hpcBadgeTitle": "Als geteilter Cluster-Login-Knoten markiert: sparsam gelesen, kein Speicherplatz-Scan oder Ordner-Zensus, keine Datei- oder Git-Synchronisierung im Hintergrund, keine automatische Erreichbarkeitsprüfung, kein stilles Auto-Verbinden, und eine Warnung, bevor irgendetwas in einer Login-Knoten-Shell läuft.",
