  "caldav.accountsButton": "CalDAV",
  "caldav.manageAccountsTitle": "CalDAV-Konten — Kalender auf einem Server, bei dem du ein Konto hast",
  "caldav.dialogNew": "CalDAV-Konto hinzufügen",
  "caldav.dialogEdit": "CalDAV-Konto",
  "caldav.intro": "Ein CalDAV-Konto synchronisiert Kalender von einem Server, bei dem du dich anmeldest. Für einen schreibgeschützten Link, den dir jemand geschickt hat, nimm stattdessen „Abonnieren“.",
  "caldav.accountName": "Name",
  "caldav.serverUrl": "Server-URL",
  "caldav.serverUrlHint": "Die Adresse des Servers – oder die des Kalenders selbst, falls dein Anbieter eine nennt. Sie steht in dessen CalDAV-Dokumentation.",
  "caldav.insecureUrl": "Diese Adresse ist unverschlüsselt (http://). Dein Passwort ginge im Klartext über die Leitung – nimm https://, außer der Server läuft auf deinem eigenen Rechner.",
  "caldav.user": "Benutzername",
  "caldav.password": "Passwort",
  "caldav.passwordHint": "Manche Server verlangen ein anwendungsspezifisches Passwort statt des normalen – sieh in den Kontoeinstellungen deines Anbieters nach, wenn die Anmeldung fehlschlägt.",
  "caldav.savePassword": "Passwort im Schlüsselbund des Systems speichern",
  "caldav.syncInterval": "Prüfen alle (Minuten)",
  "caldav.syncIntervalHint": "0 heißt nie – nur wenn du auf Synchronisieren klickst.",
  "caldav.allowWrite": "Meine \u00C4nderungen an diesen Server senden",
  "caldav.requireVpn": "Nur verbinden, solange das VPN aktiv ist",
  "caldav.requireVpnHint": "Für einen Kalenderserver, der nur aus dem eigenen Netz erreichbar ist. Solange kein OpenVPN-Tunnel steht, wird dieses Konto übersprungen statt zu scheitern, und abgeglichen, sobald einer aufgebaut ist. Nur aus {app} gestartete Tunnel zählen.",
  "caldav.allowWriteHint": "Standardm\u00E4\u00DFig aus. Solange es aus ist, sind die Kalender dieses Kontos hier schreibgesch\u00FCtzt \u2014 nichts wird gesendet, und nichts wird still zur\u00FCckgehalten. Eingeschaltet gehen \u00C4nderungen, neue Eintr\u00E4ge und L\u00F6schungen an den Server. Ein Kalender, den der Server f\u00FCr deinen Zugang als schreibgesch\u00FCtzt meldet, bleibt es in jedem Fall.",
  "caldavConflict.title": "Auch anderswo ge\u00E4ndert",
  "caldavConflict.ledeEdit": "Deine \u00C4nderung an \u201E{title}\u201C wurde nicht an den Server gesendet.",
  "caldavConflict.ledeDelete": "\u201E{title}\u201C wurde auf dem Server nicht gel\u00F6scht.",
  "caldavConflict.explain": "Die Kopie auf dem Server hat sich ge\u00E4ndert, seit dieser Rechner sie zuletzt gelesen hat \u2014 vom Handy, aus dem Web oder von einem anderen Programm. Beides sind echte \u00C4nderungen, deshalb wurde nichts \u00FCberschrieben.",
  "caldavConflict.keepMine": "Meine behalten",
  "caldavConflict.keepMineHint": "Die Version auf dem Server durch die dieses Rechners ersetzen.",
  "caldavConflict.takeServer": "Die vom Server nehmen",
