  "mail.encryption.unlockIntro": "Dieses Postfach ist mit einer Passphrase verschlüsselt. Gib sie ein, um die auf diesem Rechner gespeicherte Mail zu öffnen.",
  "mail.encryption.unlockDegraded": "Bis dahin siehst du ein vorläufiges Postfach: Mail lässt sich abrufen und lesen, es wird aber nichts gespeichert und alles ist weg, sobald {app} schließt.",
  "mail.encryption.passphrase": "Passphrase",
  "mail.encryption.passphraseConfirm": "Passphrase wiederholen",
  "mail.encryption.passphraseNoRecovery": "Diese Passphrase lässt sich nicht wiederherstellen. Wenn du sie vergisst, ist die hier gespeicherte Mail verloren — du müsstest sie löschen und neu herunterladen.",
  "mail.encryption.offerIntro": "Die Mail verschlüsseln, die {app} auf diesem Rechner ablegt, damit Nachrichten, Anhänge und Entwürfe ohne den Schlüssel unlesbar sind.",
  "mail.encryption.scopeHonest": "Was das wirklich schützt: Backups, Kopien, in die Cloud synchronisierte Ordner und Rechner, auf denen sich andere anmelden können. Es schützt nicht vor jemandem, der bei geöffnetem {app} Programme unter deinem Konto ausführen kann, und wenn deine Festplatte ohnehin verschlüsselt ist, bringt es beim gestohlenen Laptop wenig.",
  "mail.encryption.metadataHonest": "Weiterhin auf der Festplatte lesbar: wie viele Nachrichten es gibt, welche Ordner existieren sowie Datum, Größe und Gelesen-/Markiert-Status jeder Nachricht. Dafür braucht es Festplattenverschlüsselung, die auch Dateinamen verbirgt.",
  "mail.encryption.howToUnlock": "Art der Entsperrung",
  "mail.encryption.modeKeychain": "Systemschlüsselbund verwenden",
  "mail.encryption.modeKeychainHint": "Empfohlen. Dein Postfach öffnet sich ohne Nachfrage. Ist der Schlüsselbund einmal gesperrt, zeigt {app} ein vorläufiges Postfach statt gar nichts.",
  "mail.encryption.modeKeychainLocked": "Nicht verfügbar — der Systemschlüsselbund ist gesperrt oder auf diesem Rechner nicht vorhanden.",
  "mail.encryption.modePassphrase": "Nach einer Passphrase fragen",
  "mail.encryption.modePassphraseHint": "Einmal pro Sitzung eingetippt. Im Schlüsselbund wird nichts abgelegt.",
  "mail.encryption.migrationCaveat": "Hier ist bereits Mail gespeichert. Sie zu verschlüsseln schreibt die Datenbank neu und löscht die alte Kopie — auf einer SSD löscht das eine Datei aber nicht wirklich. Wenn dir das wichtig ist, nimm stattdessen Löschen und neu herunterladen.",
