  "mail.agentAccessHint": "Lesen können nur ein abgeschotteter Lese-Agent (ein Agent in einem VM-Projekt, das als „E-Mail-Leser“ markiert ist) und, wenn die Einstellungen es erlauben, ein Tab mit lokalem Modell – dieser nur die Nachrichten, die du freigibst. Was ein abgeschotteter Lese-Agent liest, wird an seinen Anbieter gesendet. Kein Agent kann senden, markieren, verschieben oder löschen. Cloud-Agenten in der Root-Konsole lesen nie E-Mails; sie können nur Entwürfe schreiben, unabhängig von dieser Einstellung.",
