  "pill.agentFenceInstall": "Bubblewrap installieren…",
  "pill.agentFenceGlyphLive": "{count} Agenten-Tab(s) dieses Projekts laufen außerhalb der Agenten-Sandbox — sie wurden gestartet, bevor sie der einzige Modus wurde. Schließen und neu öffnen, damit sie in die Sandbox kommen.",
