  "common.on": "an",
  "common.off": "aus",
  "hpcGuard.duScan.title": "Den gesamten Baum auf einem Cluster scannen?",
  "hpcGuard.duScan.body": "Dabei wird jede Datei unterhalb der Projektwurzel durchlaufen, um die Größen zu summieren. Auf einem Cluster liegt diese Wurzel normalerweise im parallelen Dateisystem, wo ein rekursiver Durchlauf eine Metadatenanfrage pro Datei an einen Server bedeutet, den der gesamte Standort teilt — genau das, wovon die Dateisystem-Leitfäden abraten. Es ist ein einzelner Scan, keine Schleife, du darfst ihn also ausführen, wenn du ihn willst.",
  "hpcGuard.duScan.go": "Trotzdem scannen",
  "hpcGuard.census.title": "Die Ordner des Hosts auf einem Cluster vermessen?",
  "hpcGuard.census.body": "Die Zählung großer Ordner führt `du` über den gesamten Host-Baum aus, um zu finden, was zu groß zum Synchronisieren ist. Gleiche Metadatenkosten wie ein vollständiger Scan, und diese Zählung läuft normalerweise beim Verbinden von selbst — deshalb bleibt sie hier aus, sofern du nicht danach fragst.",
  "hpcGuard.census.go": "Trotzdem vermessen",
  "hpcGuard.connect.title": "Bei diesem Cluster anmelden?",
  "hpcGuard.connect.body": "Diesen Tab zu öffnen würde die Maschine anwählen und dort einen gemeinsamen SSH-Master stehen lassen (und bei einem dauerhaften Tab zusätzlich einen tmux-Server) — genau die unbeaufsichtigte Präsenz, die die Markierung verhindern soll. Das ist richtig für einen beim Neustart wiederhergestellten Tab, den niemand angefordert hat; es steht nur im Weg, wenn du wirklich einen öffnen wolltest. Fortfahren verbindet zuerst das Projekt und öffnet dann den Tab.",
  "hpcGuard.connect.go": "Verbinden und öffnen",
  "hpcGuard.loginNodeRun.title": "Dies auf dem Login-Knoten ausführen?",
  "hpcGuard.loginNodeRun.body": "Dies würde auf dem Login-Knoten des Clusters laufen, den sich alle gerade angemeldeten Nutzenden teilen. Rechenzentren bitten darum, CPU-intensive Arbeit dort fernzuhalten, und behalten sich vor, Prozesse zu beenden, die ihn länger belasten. Der regelkonforme Weg für dieselbe Arbeit ist ein interaktiver Job — die srun-Shell in der Jobs-Ansicht — oder ein Batch-Skript mit sbatch.",
  "hpcGuard.loginNodeRun.go": "Trotzdem hier ausführen",
  "hpcGuard.note": "Du hast diese Maschine als Cluster-Login-Knoten markiert. Nimm die Markierung im Maschinen-Menü zurück, falls das falsch war — hier wird nichts gespeichert, es wird also beim nächsten Mal erneut gefragt.",
  "unfencedPlatform.title": "Agenten auf diesem Computer laufen mit deinen vollen Rechten",
  "unfencedPlatform.body": "Windows hat keine Agenten-Sandbox. Ein hier gestarteter Agent kann alles lesen und ändern, was dein Konto kann: andere Projekte, gespeicherte Passwörter, SSH-Schlüssel, dein Browserprofil. Unter Linux und macOS hält {app} Agenten per Sandbox in ihrem Projekt; hier geht das nicht.",
  "unfencedPlatform.alternative": "Akzeptiere, um Agenten auf diesem Computer ab jetzt zu starten — {app} fragt nur einmal. Lieber eine Grenze? Öffne das Projekt stattdessen in einem Container.",
  "unfencedPlatform.accept": "Akzeptieren und starten",
  "unfencedPlatform.declined": "Nicht gestartet: Agenten auf diesem Computer laufen mit deinen vollen Rechten, und das wurde nicht akzeptiert. Öffne einen neuen Agenten-Tab, um erneut gefragt zu werden, oder öffne das Projekt in einem Container.",
  "passwordInput.show": "Passwort anzeigen",
  "passwordInput.hide": "Passwort verbergen",
  "usage.notReadHpc": "Nicht gelesen — als HPC markiert, daher liest es nichts ungefragt.",
  "usage.notReadNoSession": "Nicht gelesen — keine Sitzung auf dieser Maschine offen.",
  "usage.readNowTitle": "Diese Maschine einmal jetzt auslesen.",
  "usage.readNowHpcTitle": "Diese Maschine einmal jetzt auslesen. Sie ist als HPC markiert, daher liest sie nichts von selbst aus.",
  "fileError.permission": "Zugriff verweigert — du hast keinen Zugriff auf diese Datei.",
  "fileError.remoteMissing": "Diese Datei liegt nicht auf dem entfernten Host — sie ist möglicherweise nur lokal vorhanden (nie synchronisiert). Stelle den Betrachter auf „Lokal“, um sie zu öffnen.",
  "fileError.missing": "Diese Datei existiert nicht mehr.",
