  "rootConsole.rightsBadge": "⚿ {app}-Werkzeuge",
  "rootConsole.rightsLocalOnly": "Nur hier geöffnete Tabs mit lokalem Modell erhalten {app}s eigene Werkzeuge (MCP): deine Projekte, den Kalender und das To-do-Board. Cloud-Agenten und die Agenten eines Projekts erhalten sie nicht.",
  "rootConsole.rightsOn": "Hier geöffnete Agenten erhalten {app}s eigene Werkzeuge (MCP): deine Projekte, den Kalender und das To-do-Board. Die Agenten eines Projekts erhalten sie nicht.",
  "rootConsole.rightsOff": "{app}s Werkzeuge laufen nicht – hier geöffnete Agenten sind gewöhnliche Agenten, bis {app} neu gestartet wird.",
  "rootConsole.rightsDisabled": "{app}s Werkzeuge (MCP) sind ausgeschaltet – Agenten hier sind gewöhnliche Agenten, bereits laufende werden abgewiesen.",
  "rootConsole.rightsInSettings": "Was ein Root-Tab mit diesen Werkzeugen darf, wird in den Einstellungen ein- und ausgeschaltet.",
  "rootConsole.noPhone": "Die Root-Konsole wird weder {app} Mobile noch Claudes Fernsteuerung angeboten.",
  "rootConsole.mailOpen": "Mindestens ein E-Mail-Konto gibt markierte Nachrichten für E-Mail-lesende Agenten frei: einen abgeschotteten Lese-Agenten oder, wo die Einstellungen es erlauben, einen Tab mit lokalem Modell. Cloud-Root-Tabs lesen weiterhin keine E-Mails; sie können nur Entwürfe schreiben.",
  "rootConsole.mailOpenAll": "Mindestens ein E-Mail-Konto ist vollständig für einen abgeschotteten Lese-Agenten geöffnet; ein Tab mit lokalem Modell sieht, wo die Einstellungen es erlauben, weiterhin nur die markierten Nachrichten. Cloud-Root-Tabs lesen weiterhin keine E-Mails; sie können nur Entwürfe schreiben.",
  "rootConsole.reviewAdvisory": "Die Prüfung wird nicht erzwungen: Root-Agenten laufen ohne die Agenten-Sandbox, daher kann ein Agent Kalender, Board oder diese Prüfeinstellung direkt ändern, ohne Vorschlag. Schalte die Sandbox ein, damit die Prüfung eine Schranke ist.",
